L6_1.m_CharOffSet = L7_1
L6_1.m_Talk_KOREA = "저는 못다한 이야기를 하러 왔을 뿐입니다, 그레이스 경."
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "私は、果たせなかった話をしに来ただけです、グレース卿。"
L6_1.m_Talk_ENG = "I came only to finish what was left unsaid, Dame Grace."
L6_1.m_Talk_TWN = "我只是來講述未完的故事，葛瑞絲小姐。"
L6_1.m_Talk_SCN = "我只是来讲述未完的故事，格蕾丝爵士。"
L6_1.m_Talk_DEU = "I came only to finish what was left unsaid, Dame Grace."
L6_1.m_Talk_FRA = "I came only to finish what was left unsaid, Dame Grace."
