L14_1.m_CharStrID = "ESTAROSSA_NPC_NULL_NULL"
L14_1.m_Talk_KOREA = "경께서 말씀하신 악몽의 계기는 늘상 같았고, 그 악몽이 보여주는 것 또한 동일했죠."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "卿がおっしゃっていた悪夢のきっかけはいつも同じで、その悪夢が見せてくれることもまた同じでした。"
L14_1.m_Talk_ENG = "The nightmare you spoke of always began the same way and showed the same things."
L14_1.m_Talk_TWN = "你所說的惡夢的起因總是相同，而惡夢所展示的內容也一樣。"
L14_1.m_Talk_SCN = "您所说的噩梦的起因总是相同，而噩梦所展示的内容也一样。"
L14_1.m_Talk_DEU = "The nightmare you spoke of always began the same way and showed the same things."
L14_1.m_Talk_FRA = "The nightmare you spoke of always began the same way and showed the same things."
