L22_1.m_Talk_SCN = "至今为止多次守护我的……星之庇佑。"
L22_1.m_Talk_DEU = "You've protected me countless times... You're the Blessing of the Stars."
L22_1.m_Talk_FRA = "You've protected me countless times... You're the Blessing of the Stars."
