L30_1.m_CharScale = L31_1
L30_1.m_CharScaleTime = 0.01
L30_1.m_Talk_KOREA = "기연으로 사도가 되는 것은 피했으나 제 근원은 네헤모트와 동일한 세계에서 비롯된 것."
L30_1.m_fTalkTime = 0.03
