L31_1.m_fTalkTime = 0.03
L31_1.m_Talk_JPN = "カランティシルはそれを知っているので、武具に宿っているクリファで星の光を侵食させようとしているのでしょうが……"
L31_1.m_Talk_ENG = "Carantisir knows this. That's why he's trying to corrupt the starlight with Qlipha from the Armament..."
