L37_1 = "AB_UI_UNIT_VOICE_OPR_GRACE_IN_TRAILER_16"
L36_1.m_VoiceFileName = L37_1
L36_1.m_CharStrID = "GRACE_ORDER_NULL_NULL"
L36_1.m_Pos = "R"
L37_1 = "많은 사람들은 인도자의 무구를 떠받치며 그들의 전승을 신화처럼 여기지만."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "多くの人は導き手の武具を崇め、彼らの伝承を神話のように思っているのですが。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Many revere the Star Guide's Armament and consider the legend as myth."
L36_1.m_Talk_ENG = L37_1
L37_1 = "許多人將引導者的無垢視為神話般的傳說，崇拜著他們的勝利。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "许多人将引导者的无垢视为神话般的传说，崇拜着他们的胜利。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Many revere the Star Guide's Armament and consider the legend as myth."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Many revere the Star Guide's Armament and consider the legend as myth."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "PRIDE_ACT5_STAGE3_END@25#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 37
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 7600509
L37_1.m_CutScenStrID = "PRIDE_ACT5_STAGE3_END"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "AB_UI_UNIT_VOICE_OPR_GRACE_IN_TRAILER_17"
L37_1.m_VoiceFileName = L38_1
L37_1.m_CharStrID = "GRACE_ORDER_NULL_NULL"
L37_1.m_Pos = "R"
L38_1 = "실상 별의 무구에 담긴 별빛은 인도자의 운명을 빚어낸 것에 불과합니다."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "実際星の武具に込められている星の光は、導き手の運命を打ち鍛えたものに過ぎません。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "But the starlight within only exists to shape the Guide's fate."
L37_1.m_Talk_ENG = L38_1
L38_1 = "實際上，星之武具中的星光不過是塑造了引導者的命運。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "实际上，星辰武器中的星光不过是塑造了引导者的命运。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "But the starlight within only exists to shape the Guide's fate."
L37_1.m_Talk_DEU = L38_1
L38_1 = "But the starlight within only exists to shape the Guide's fate."
L37_1.m_Talk_FRA = L38_1
