L41_1.m_Pos = "C"
L42_1 = "방식이 달라졌을 뿐, 제 운명은 처음부터 정해져 있었습니다."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "方法が異なっているだけで、私の運命は最初から決まっていました。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "My fate was set from the start. Only the method has changed."
L41_1.m_Talk_ENG = L42_1
L42_1 = "只是方式改變了，我的命運從一開始就已經註定了。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "只是方式改变了，我的命运从一开始就已经注定了。"
