L42_1.m_Pos = "C"
L43_1 = "멸망한 옛 고향에 미련이 남아 애써 그것을 붙잡고 있었으나……."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "滅亡した昔の故郷に未練を感じ、頑張ってそれを引き止めてはいたのですが……"
L42_1.m_Talk_JPN = L43_1
L43_1 = "I clung to my ruined homeland out of regret..."
L42_1.m_Talk_ENG = L43_1
L43_1 = "對已毀滅的故鄉仍有留戀，努力想要抓住它……"
L42_1.m_Talk_TWN = L43_1
L43_1 = "对已毁灭的故乡仍有留恋，努力想要抓住它……。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "I clung to my ruined homeland out of regret..."
