L43_1.m_Pos = "C"
L44_1 = "결국 모든 것이 제자리로 돌아갈 뿐입니다."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "結局、すべてはあるべき場所に戻るだけです。"
