L44_1.m_Pos = "C"
L45_1 = "더 이상 여러분의 정의를 추구하는데 별의 인도를 따를 필요는 없어요."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "もう皆さんの正義を追求するのに、星の導きに従う必要はありません。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "There's no need to follow the star's guidance to seek justice."
L44_1.m_Talk_ENG = L45_1
L45_1 = "不再需要依靠星之引導來追求你們的正義了。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "不再需要依靠星星的指引来追求你们的正义了。"
