L46_1 = "패배자의 길을 답습하기만 해서야 경께서 원하시는 기사는 될 수 없을 겁니다."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "敗北者の道をたどることだけでは、卿がお望みの騎士にはなれないはずですもの。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "So long as you only repeat a loser's path, you'll never become the knight you wish to be."
L45_1.m_Talk_ENG = L46_1
L46_1 = "如果只是重複失敗者的道路，是無法成為你所期望的騎士的。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "如果只是重复失败者的道路，是无法成为您所期望的骑士的。"
