L16_1.m_CharOffSet = L17_1
L17_1 = "전부 그레이스 경께서 남겨 주신… 기사단이 제게 안겨준 소중한 추억입니다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "全部、グレース卿が残してくれた……騎士団が私に与えてくれた大切な思い出です。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Those are the memories you left me... The Order gave me that gift."
L16_1.m_Talk_ENG = L17_1
L17_1 = "全部都是葛瑞絲小姐留下的……騎士團給予我的珍貴回憶。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "全部都是格蕾丝阁下留下的……骑士团给予我的珍贵回忆。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Those are the memories you left me... The Order gave me that gift."
