L18_1[2] = L20_1
L17_1.m_CharOffSet = L18_1
L18_1 = "별의 인도가 거짓일지 언정, 당신이라는 별은 모두를 이끌었어요."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "星の導きが嘘であるとしても、あなたという星はみんなを導いてくれました。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Even if the guidance of the stars was false, your light led us all."
L17_1.m_Talk_ENG = L18_1
L18_1 = "即便星之引導者是虛假的，你這顆星星也引領了所有人。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "即便星辰的指引是虚假的，你这颗星星也引领了所有人。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Even if the guidance of the stars was false, your light led us all."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Even if the guidance of the stars was false, your light led us all."
L17_1.m_Talk_FRA = L18_1
