L18_1.m_VoiceFileName = L19_1
L18_1.m_CharStrID = "GRACE_ORDER_NULL_NULL"
L18_1.m_Pos = "C"
L19_1 = "빛나지 않는 별이라 한들 한순간의 이정표로 삼을 수는 있겠지요."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "光らない星だとしても、一瞬の道しるべと思うことはできます。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Even a dim star can be a guide, if only for a moment."
L18_1.m_Talk_ENG = L19_1
L19_1 = "即使是不閃耀的星星，也可以成為瞬間的路標吧。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "即使是不闪耀的星星，也可以成为瞬间的路标吧。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Even a dim star can be a guide, if only for a moment."
