L20_1.m_VoiceFileName = L21_1
L20_1.m_CharStrID = "GRACE_ORDER_NULL_NULL"
L20_1.m_Pos = "C"
L21_1 = "세상에 온전한 구원은 없고, 저희가 걸어 나간 길의 끝은 낭떠러지니까요."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "世界に完全な救いはなく、私たちが歩いてきた道の果てには崖があるのですから。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "There is no true salvation. Only cliffs await at the end of our path."
L20_1.m_Talk_ENG = L21_1
L21_1 = "這個世界沒有完美的救贖，我們走過的路盡頭是懸崖。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "这个世界没有完美的救赎，我们走过的路尽头是悬崖。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "There is no true salvation. Only cliffs await at the end of our path."
L20_1.m_Talk_DEU = L21_1
