L23_1.m_CharStrID = "GRACE_ORDER_NULL_NULL"
L23_1.m_Pos = "C"
L24_1 = "예. 차디찬 고독이, 못다 건넨 말이 첨예되어 미련으로 남아있지요."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "はい。冷たい孤独が、伝えられなかった言葉が、研ぎ澄まされては未練として残っています。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Yes. Bitter loneliness. And unsaid words sharpened into regret."
L23_1.m_Talk_ENG = L24_1
L24_1 = "是的。冰冷的孤獨，未曾說出口的話語化作尖銳的執念，仍然留存於心。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "是的。冰冷的孤独，未曾说出口的话语化作尖锐的执念，仍然留存于心。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Yes. Bitter loneliness. And unsaid words sharpened into regret."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Yes. Bitter loneliness. And unsaid words sharpened into regret."
L23_1.m_Talk_FRA = L24_1
