L24_1.m_CharOffSet = L25_1
L25_1 = "고통스러운 최후일지 언정, 그곳에 다다르기 전 그 길을 걸어갔음을."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
