L24_1.m_Talk_JPN = L25_1
L25_1 = "Even if the end was painful, after reaching the end of the path..."
L24_1.m_Talk_ENG = L25_1
L25_1 = "即便是痛苦的終結，也要在抵達之前走過那條路。"
