L7_1 = "AB_UI_UNIT_VOICE_OPR_GRACE_IN_TRAILER_34"
L6_1.m_VoiceFileName = L7_1
L6_1.m_CharStrID = "GRACE_ORDER_NULL_NULL"
L7_1 = "부족하게나마 내일을 맞이하기 위해 희망이라는 단어를 비추려 노력하는."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "微力ながらも、明日を迎えるために希望を照らそうと努力する。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "They try, however clumsily, to greet tomorrow with hope."
L6_1.m_Talk_ENG = L7_1
L7_1 = "儘管微不足道，但仍努力讓希望之光照亮明天。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "尽管微不足道，但仍努力用希望这个词来迎接明天。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "They try, however clumsily, to greet tomorrow with hope."
L6_1.m_Talk_DEU = L7_1
L7_1 = "They try, however clumsily, to greet tomorrow with hope."
L6_1.m_Talk_FRA = L7_1
