L18_1.m_Pos = "C"
L19_1 = "그리고… 소중한 사람들이 곁에 있어주는 이곳이 좋습니다."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "そして……大切な人々がそばにいてくれるここが、好きです。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "And... I love this place where those dear to me are close by."
L18_1.m_Talk_ENG = L19_1
L19_1 = "而且……我喜歡有珍貴的人陪伴在身邊的這個地方。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "而且…我喜欢有珍贵的人陪伴在身边的这个地方。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "And... I love this place where those dear to me are close by."
