L19_1.m_Pos = "C"
L20_1 = "좋아하는 걸 지키기 위해 제 한 몸 불사르는 것을 어찌 희생이라 할 수 있겠나요."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "好きなものを守るために自分の体を張ることを犠牲とは言えません。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "If I burn myself up to protect the things I love, how could that ever be called sacrifice?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "為了守護我所愛的東西，獻出我的生命又怎能稱為犧牲呢。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "为了守护所爱之物而奋不顾身，怎能称之为牺牲呢？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "If I burn myself up to protect the things I love, how could that ever be called sacrifice?"
L19_1.m_Talk_DEU = L20_1
L20_1 = "If I burn myself up to protect the things I love, how could that ever be called sacrifice?"
L19_1.m_Talk_FRA = L20_1
