L6_1 = "AB_UI_UNIT_VOICE_OPR_GRACE_IN_TRAILER_43"
L5_1.m_VoiceFileName = L6_1
L5_1.m_CharStrID = "GRACE_ORDER_NULL_NULL"
L6_1 = "……수 세기가 지나 사랑하던 이의 목소리조차 희미해진 기억이 못내 원망스러워도."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "……数世紀が過ぎて、愛する人の声すらもおぼろげになってしまった記憶が恨めしくても。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "...Even if centuries pass and I forget the voice I loved."
L5_1.m_Talk_ENG = L6_1
L6_1 = "……即使經過了幾個世紀，連愛人的聲音都變得模糊不清的記憶仍然令人怨恨。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "……即使经过了几个世纪，连爱人的声音都变得模糊不清的记忆仍然令人怨恨。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "...Even if centuries pass and I forget the voice I loved."
L5_1.m_Talk_DEU = L6_1
L6_1 = "...Even if centuries pass and I forget the voice I loved."
