L7_1.m_VoiceFileName = L8_1
L7_1.m_CharStrID = "GRACE_ORDER_NULL_NULL"
L8_1 = "에스테로사 경. 못다한 <color=#ffd34c>질문</color>에 답을 하면, 우리에게 후회란 없습니다."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "エステロサ卿。まだ答えられなった<color=#ffd34c>質問</color>にお答えしますと、私たちに後悔などありません。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Esterosa. If I answer that unfinished <color=#ffd34c>question</color>, there will be no regrets."
L7_1.m_Talk_ENG = L8_1
L8_1 = "艾斯特洛索。回答未盡的<color=#ffd34c>問題</color>，我們就不會有遺憾。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "艾索阁下。回答未尽的<color=#ffd34c>问题</color>，我们就不会有遗憾。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Esterosa. If I answer that unfinished <color=#ffd34c>question</color>, there will be no regrets."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Esterosa. If I answer that unfinished <color=#ffd34c>question</color>, there will be no regrets."
L7_1.m_Talk_FRA = L8_1
