L8_1.m_CharStrID = "GRACE_ORDER_NULL_NULL"
L9_1 = "오랜 기다림 끝에 비로소…… 소임을 다하였으니."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "待ちに待ったこの日、やっと……役目を果たせた。"
