L13_1 = "AB_UI_UNIT_VOICE_OPR_GRACE_IN_TRAILER_47"
L12_1.m_VoiceFileName = L13_1
L12_1.m_CharStrID = "GRACE_ORDER_NULL_NULL"
L13_1 = "기사의 명예란 맹세에 어긋나지 않는 길을 걸으면 자연스레 빛나는 법."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "騎士の名誉とは、誓った道をひたすら歩けば自ずと輝くもの。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "A knight's honor shines brightest when they walk a path true to their vow."
L12_1.m_Talk_ENG = L13_1
L13_1 = "所謂騎士的名譽，只要堅守誓言，有一天自然會發光。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "所谓骑士的名誉，只要坚守誓言，有一天自然会发光。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "A knight's honor shines brightest when they walk a path true to their vow."
L12_1.m_Talk_DEU = L13_1
L13_1 = "A knight's honor shines brightest when they walk a path true to their vow."
L12_1.m_Talk_FRA = L13_1
