L14_1 = "PRIDE_ACT5_STAGE3_END@98#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 163
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 7600509
