L14_1 = "AB_UI_UNIT_VOICE_OPR_GRACE_IN_TRAILER_48"
L13_1.m_VoiceFileName = L14_1
L13_1.m_CharStrID = "GRACE_ORDER_NULL_NULL"
L14_1 = "그대들의 주인은 오직 고통받는 이들일지니, 운명에 희생된 비통한 목소리를 대신하여 이 영광된 의식을 거행한다."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "そなたたちの主は苦しみに満ちた者たちのみ。運命の犠牲となった悲痛な声に代わり、この栄光なる儀式を執り行おう。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "You serve no one but the afflicted. I hereby officiate this honorable ceremony on behalf of the mournful voices silenced by fate."
L13_1.m_Talk_ENG = L14_1
L14_1 = "你們的主人是那些受苦的人，我在此代替那些哀痛的聲音，舉行這榮耀的儀式。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "你们的主人即是受苦的弱者。在此，我将代替那些因命运而牺牲的悲痛声音，举行这光荣的仪式。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "You serve no one but the afflicted. I hereby officiate this honorable ceremony on behalf of the mournful voices silenced by fate."
L13_1.m_Talk_DEU = L14_1
L14_1 = "You serve no one but the afflicted. I hereby officiate this honorable ceremony on behalf of the mournful voices silenced by fate."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
