L15_1 = "AB_UI_UNIT_VOICE_OPR_GRACE_IN_TRAILER_49"
L14_1.m_VoiceFileName = L15_1
L14_1.m_CharStrID = "GRACE_ORDER_NULL_NULL"
L15_1 = "성좌의 광명을 따르며 만인을 지키기로 맹세할 자, 누구인가?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "星座の光明に従い、万人を守ると誓う者は誰だ。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Who pledges today to follow the radiance of the constellations and protect humanity?"
L14_1.m_Talk_ENG = L15_1
L15_1 = "跟從星座之光，宣示要守護萬民的人，是誰？"
L14_1.m_Talk_TWN = L15_1
L15_1 = "誓言追随星座的光辉，守护众生的人，究竟是谁？"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Who pledges today to follow the radiance of the constellations and protect humanity?"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Who pledges today to follow the radiance of the constellations and protect humanity?"
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
