L16_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_IN_TRAILER_60"
L15_1.m_VoiceFileName = L16_1
L15_1.m_CharStrID = "ESTAROSSA_NPC_NULL_NULL"
L16_1 = "……에스테로사. 드높은 별의 인도로 이 자리에 섰습니다."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "……エステロサ、誇り高き星の導きよりこの場に辿り着きました。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "...I, Esterosa, stand here under the guidance of the stars."
L15_1.m_Talk_ENG = L16_1
L16_1 = "我 艾斯特洛索，跟從正義之星的引導站立在這位置上。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "……艾索。受高悬之星的指引而站在此处。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "...I, Esterosa, stand here under the guidance of the stars."
L15_1.m_Talk_DEU = L16_1
L16_1 = "...I, Esterosa, stand here under the guidance of the stars."
L15_1.m_Talk_FRA = L16_1
