L17_1 = "PRIDE_ACT5_STAGE3_END@101#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 166
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 7600509
L16_1.m_CutScenStrID = "PRIDE_ACT5_STAGE3_END"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "AB_UI_UNIT_VOICE_OPR_GRACE_IN_TRAILER_50"
L16_1.m_VoiceFileName = L17_1
L16_1.m_CharStrID = "GRACE_ORDER_NULL_NULL"
L17_1 = "그대는 길을 잃어 어둠 속을 헤매는 이들에게 무엇을 맹세하겠는가?"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "そなたは道に迷い、闇の中で彷徨う者たちに何を誓うか。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "And what do you vow, to those who wander lost in the dark?"
L16_1.m_Talk_ENG = L17_1
L17_1 = "你會對那些在黑暗中迷失方向的人們許下什麼誓言？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "你会对那些在黑暗中迷失方向的人们许下什么誓言？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "And what do you vow, to those who wander lost in the dark?"
L16_1.m_Talk_DEU = L17_1
L17_1 = "And what do you vow, to those who wander lost in the dark?"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "PRIDE_ACT5_STAGE3_END@102#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 167
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 7600509
L17_1.m_CutScenStrID = "PRIDE_ACT5_STAGE3_END"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_IN_TRAILER_61"
L17_1.m_VoiceFileName = L18_1
L17_1.m_CharStrID = "ESTAROSSA_NPC_NULL_NULL"
L18_1 = "적막한 밤의 평화. 별처럼 빛나는 희망."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "寂寞たる夜の平和。星のごとく光る希望。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "The peace of a quiet night. Hope that shines like the stars."
L17_1.m_Talk_ENG = L18_1
L18_1 = "我宣示，寂靜的夜晚中有和平，希望如星閃耀，以及黎明必將到來。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "长夜寂静，和平永存，群星闪耀，希望尤在。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "The peace of a quiet night. Hope that shines like the stars."
L17_1.m_Talk_DEU = L18_1
L18_1 = "The peace of a quiet night. Hope that shines like the stars."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "PRIDE_ACT5_STAGE3_END@103#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 168
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 7600509
L18_1.m_CutScenStrID = "PRIDE_ACT5_STAGE3_END"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_IN_TRAILER_62"
L18_1.m_VoiceFileName = L19_1
L18_1.m_CharStrID = "ESTAROSSA_NPC_NULL_NULL"
L19_1 = "여러분들이 보지 못한, 내일의 새벽을 맞이하리라는 믿음을 맹세합니다."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "皆さんが見ることができなかった、次の夜明けが訪れると信じる心を誓います。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "And the promise that even if unseen, we will greet the dawn together."
L18_1.m_Talk_ENG = L19_1
L19_1 = "諸位，我在此向你等立下誓言，明天的黎明終將會到來。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "诸位，我在此向你等立下誓言，明天的黎明终将会到来。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "And the promise that even if unseen, we will greet the dawn together."
L18_1.m_Talk_DEU = L19_1
L19_1 = "And the promise that even if unseen, we will greet the dawn together."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "PRIDE_ACT5_STAGE3_END@104#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 169
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 7600509
L19_1.m_CutScenStrID = "PRIDE_ACT5_STAGE3_END"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "AB_UI_UNIT_VOICE_OPR_GRACE_IN_TRAILER_51"
L19_1.m_VoiceFileName = L20_1
L19_1.m_CharStrID = "GRACE_ORDER_NULL_NULL"
L20_1 = "그대들의 기원인 별의 인도자이자, 스러져간 별들을 대신하여 이 자리에서 선언한다."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "そなたたちの起源である星の導き手であり、消えていった星々の代わりにこの場で宣言する。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "As the Star Guide and voice of the fallen, I proclaim this now."
L19_1.m_Talk_ENG = L20_1
L20_1 = "我在此宣告，作為你們祈願的星之引導者，代替那些隕落的星星。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "我在此宣告，作为你们祈愿之星的引导者，代替那些陨落的星星。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "As the Star Guide and voice of the fallen, I proclaim this now."
L19_1.m_Talk_DEU = L20_1
L20_1 = "As the Star Guide and voice of the fallen, I proclaim this now."
L19_1.m_Talk_FRA = L20_1
